// a^e mod m을 빠르게 구한다
long long power(long long a, long long e, long long m) {
    long long r = 1, b = a % m;
    while (e > 0) {                // 이 반복이 몇 번 도는가
        if (e & 1) r = r * b % m;  // e의 현재 비트가 1이면 곱한다
        b = b * b % m;             // b를 제곱해 다음 비트로
        e >>= 1;
    }
    return r;
}

